const $=s=>document.querySelector(s);
const icons={cloud:'M7 18a5 5 0 0 1-1-9.9 7 7 0 0 1 13-1A5.5 5.5 0 0 1 18 18Z',home:'m3 10 9-7 9 7M5 9v12h5v-7h4v7h5V9',chat:'M21 11a9 9 0 0 1-9 9 10 10 0 0 1-4-.8L3 21l1.7-5A9 9 0 1 1 21 11ZM8 11h.01M12 11h.01M16 11h.01',file:'M14 2H5v20h14V7Zm0 0v6h5M8 12h8M8 16h8',image:'M4 3h16a1 1 0 0 1 1 1v16a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1ZM3 17l6-6 5 5 3-3 4 4M8 7h.01',history:'M3 12a9 9 0 1 0 3-7M3 3v6h6M12 7v6l4 2',plus:'M12 4v16M4 12h16',arrow:'M5 12h14m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',user:'M20 21v-2a7 7 0 0 0-14 0v2M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',grid:'M3 3h6v6H3ZM15 3h6v6h-6ZM3 15h6v6H3ZM15 15h6v6h-6Z',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6Zm-4 9 3 3 5-6',signal:'M12 20V10M8 16a6 6 0 0 1 0-9M16 16a6 6 0 0 0 0-9M5 19a10 10 0 0 1 0-15M19 19a10 10 0 0 0 0-15',chip:'M6 6h12v12H6ZM9 9h6v6H9ZM9 2v4M15 2v4M9 18v4M15 18v4M2 9h4M2 15h4M18 9h4M18 15h4',users:'M16 21v-2a5 5 0 0 0-10 0v2M15 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M18 4a4 4 0 0 1 0 7M20 15a5 5 0 0 1 2 4v2M3 15a5 5 0 0 0-2 4',building:'M5 22V4l14-2v20M9 7h2M14 6h2M9 11h2M14 10h2M9 15h2M14 14h2M10 22v-4h4v4',chart:'M5 21v-6M12 21V9M19 21V3',play:'m8 4 12 8-12 8Z',upload:'M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6',paperclip:'m8 13 7-7a3 3 0 0 1 4 4l-9 9a5 5 0 0 1-7-7L13 2M7 14l9-9',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3ZM20 2v4M18 4h4',settings:'m9 3-1 3-3 1-2 4 2 2v4l4 3 3-1 3 1 4-3v-4l2-2-2-4-3-1-1-3Zm7 9a4 4 0 1 1-8 0 4 4 0 0 1 8 0',help:'M9 8a3 3 0 1 1 4 3c-1 0-1 2-1 3M12 18h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',logout:'M10 3H3v18h7M8 12h14m-5-5 5 5-5 5',folder:'M3 6V3h6l3 3h9v14H3Z',check:'m5 12 4 4L19 6',link:'m10 14 4-4M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0M16 8l2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',bulb:'M9 18h6M9 22h6M8 14a7 7 0 1 1 8 0l-1 4H9Z',box:'m12 2 10 5v10l-10 5-10-5V7Zm0 10v10M2 7l10 5 10-5',download:'M12 3v13m-5-5 5 5 5-5M3 17v5h18v-5',trash:'M3 6h18M8 6V3h8v3M5 6l1 16h12l1-16M10 10v8M14 10v8',menu:'M3 6h18M3 12h18M3 18h18',close:'m6 6 12 12M6 18 18 6',sliders:'M6 3v18M12 3v18M18 3v18M3 8h6M9 16h6M15 7h6'};
function icon(n,cl=''){return `<svg class="icon ${cl}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.spark}"/></svg>`}
function brand(){return `<a class="brand" href="#landing" aria-label="CloudCore AI landing page"><span class="brand-symbol">${icon('cloud')}<i></i></span><span><strong>CloudCore <b>AI</b></strong><small>A product of PTCL Smart Cloud</small></span></a>`}
function wave(cl=''){return `<svg class="wave ${cl}" viewBox="0 0 1400 260" preserveAspectRatio="none" aria-hidden="true">${Array.from({length:34},(_,i)=>`<path d="M-100 ${95+i*2} C210 ${-150+i*9}, 350 ${400-i*2}, 680 ${135+i} S 850 ${-40+i*6}, 1100 ${100+i*3} S1350 ${260-i*4},1500 ${55+i*3}"/>`).join('')}</svg>`}
function footer(){return `<footer class="page-footer"><span>Technology that moves Pakistan forward.</span><i></i><span>${icon('cloud')} A product of PTCL Smart Cloud</span></footer>`}
function landing(){return `<div class="landing"><div class="hero-backdrop"></div><header class="landing-header">${brand()}<nav aria-label="Main navigation"><a class="active" href="#landing">Home</a><a href="#home">Solutions</a><a href="#assistant">AI Assistant</a><a href="#documents">Resources</a><a href="#about">About</a></nav><a class="landing-search" href="#home">${icon('search')}<span>Search solutions, insights, or support...</span></a><button class="icon-button notification" aria-label="Notifications" data-action="notifications">${icon('bell')}<i></i></button><a class="sign-in" href="#home">${icon('user')}<span>Sign In</span></a></header><main><section class="hero"><div class="eyebrow">CLOUDCORE AI</div><h1>Smarter Connections<br><span>for a Stronger Tomorrow</span></h1><p>Your AI-powered partner for business solutions,<br>insights and support — from PTCL Smart Cloud.</p><div class="hero-actions"><a class="primary" href="#home">${icon('chat')} Chat with CloudCore AI ${icon('arrow')}</a><a class="explore" href="#home"><span>${icon('play')}</span> Explore Our Solutions</a></div><div class="hero-motto">People<br>Technology<br><b>A Brighter Pakistan</b><i></i></div><div class="signature">Connected<br><span>for a Better</span><br><em>Tomorrow</em></div></section><section class="service-strip" aria-label="Our solutions">${[['signal','Reliable Connectivity','Keep your business always on'],['cloud','Cloud & Data Solutions','Scale with confidence'],['shield','Cyber Security','A safer, stronger tomorrow'],['chip','AI-Powered Support','Instant answers. Real progress.']].map(([i,t,d])=>`<a href="#assistant" class="service-card"><span class="service-icon">${icon(i)}</span><span><strong>${t}</strong><small>${d}</small></span>${icon('chevron')}</a>`).join('')}</section><section class="impact" id="about">${wave()}<div class="impact-intro"><div class="eyebrow">POWERING PAKISTAN’S BUSINESS GROWTH</div><h2>Technology that moves<br><span>Pakistan forward.</span></h2><p>From intelligent connectivity to cloud, security and AI —<br>PTCL Smart Cloud helps organizations work smarter,<br>grow faster and build a more connected Pakistan.</p><a class="outline small" href="#home">Learn More ${icon('arrow')}</a></div><div class="stats">${[['users','10,000+','Business Customers'],['building','200+','Enterprise Partners'],['cloud','99.9%','Network Reliability'],['chart','A Stronger<br>Pakistan','Our Shared Purpose']].map(([i,t,d])=>`<article class="stat"><span>${icon(i)}</span><h3>${t}</h3><p>${d}</p><i></i></article>`).join('')}</div></section></main><footer class="landing-footer">${brand()}<span class="footer-credit">A product of PTCL Smart Cloud</span><div><button data-action="privacy">Privacy</button><button data-action="terms">Terms</button><a href="#assistant">Contact</a><span class="connected">A Connected Pakistan. <i></i></span></div></footer></div>`}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function route(){const r=location.hash.slice(1)||'landing';$('#app').innerHTML=(r==='landing'||r==='about')?landing():workspace(r);bind();window.scrollTo(0,0);if(r==='about')$('#about').scrollIntoView({behavior:'smooth'});}
function bind(){document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{const a=el.dataset.action;if(a==='notifications')toast('You’re all caught up. No new notifications.');else if(a==='privacy')toast('This frontend stores chat history on this device only.');else if(a==='terms')toast('CloudCore AI frontend preview. AI services are not connected.');else actions(a,el)});}
let messages=[],currentChat=null,docFile=null,imageFile=null,imageURL='',docTab='Summary',imageMode='upload',historySearch='';
let chats=[];try{chats=JSON.parse(localStorage.getItem('cloudcore-chats')||'[]')}catch{}
const navs=[['home','home','Home'],['assistant','chat','AI Assistant'],['documents','file','Document Insight'],['images','image','Image Analysis'],['history','history','Chat History']];
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function sidebar(r){return `<aside class="sidebar">${brand()}<button class="primary new-chat" data-action="new-chat">${icon('plus')} New Chat</button><nav aria-label="Product navigation">${navs.map(([id,i,t])=>`<a href="#${id}" class="${r===id?'selected':''}">${icon(i)}<span>${t}</span></a>`).join('')}</nav><div class="sidebar-bottom"><button data-action="settings">${icon('settings')}<span>Settings</span></button><button data-action="help">${icon('help')}<span>Help</span></button><a href="#landing">${icon('logout')}<span>Back to website</span></a><div class="cloud-credit">${icon('cloud')}<span>A product of<strong>PTCL Smart Cloud</strong></span></div></div></aside>`}
function workspace(r){if(!navs.some(n=>n[0]===r))r='home';return `<div class="workspace ${r}-workspace">${sidebar(r)}<div class="workspace-body"><header class="workspace-header"><button class="mobile-menu icon-button" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><form class="global-search" id="search-form">${icon('search')}<input aria-label="Search products, guides, solutions" placeholder="Search products, guides, solutions..."></form><div class="user-controls"><button class="icon-button notification" data-action="notifications" aria-label="Notifications">${icon('bell')}<i></i></button><button class="user-menu" data-action="profile"><span class="avatar">A</span><span><small>Welcome,</small><strong>Ali</strong></span><span class="down">⌄</span></button></div></header><main class="workspace-main">${wave('workspace-wave')}${r==='home'?home():r==='documents'?documents():r==='images'?images():r==='history'?history():assistant()}</main>${footer()}</div></div><input hidden type="file" id="document-input" accept=".pdf,.docx,.pptx,.xlsx,.txt,.md"><input hidden type="file" id="image-input" accept="image/png,image/jpeg,image/webp"><dialog id="dialog"><button class="dialog-close icon-button" data-action="close-dialog" aria-label="Close">${icon('close')}</button><div id="dialog-content"></div></dialog>`}
function home(){return `<section class="home-intro"><h1>Hello Ali,<br><span>How can I help you today?</span></h1><p>Get answers, analyze documents, understand images, explore PTCL solutions<br>and more — all in one place.</p><div class="workspace-motto">Smarter AI.<br>Stronger Business.<br><b>A Connected Pakistan.</b></div></section>${composer('home')}<div class="suggestions"><span>Try asking:</span>${['Our enterprise internet plans','Summarize this document','What is in this image?','Compare cloud solutions','Help with a proposal'].map(t=>`<button data-action="suggestion" data-prompt="${t}">${t}</button>`).join('')}</div><section class="home-cards">${[['chat','Chat & Ask','Get instant answers<br>from PTCL knowledge','Start chatting','assistant'],['file','Analyze Documents','Upload PDF, contracts,<br>reports and get insights','Upload a document','documents'],['image','Understand Images','Upload an image<br>(e.g. network equipment,<br>screenshots, diagrams)','Upload an image','images'],['grid','Explore Solutions','Discover PTCL Business<br>Solutions for your industry','Browse solutions','solutions']].map(([i,t,d,c,r])=>`<article><span class="feature-icon">${icon(i)}</span><h2>${t}</h2><p>${d}</p><${r==='solutions'?'button data-action="solutions"':'a href="#'+r+'"'}>${c} ${icon('arrow')}</${r==='solutions'?'button':'a'}></article>`).join('')}</section><div class="mountain-banner"><h2>Technology that<br>moves Pakistan forward.<i></i></h2><span>A Brighter<br><b>Pakistan</b></span></div>`}
function composer(id){return `<form class="composer" id="${id}-composer"><div><input name="prompt" aria-label="Message CloudCore AI" placeholder="${id==='home'?'Ask anything about PTCL, our services, documents, or upload an image...':'Ask CloudCore AI anything...'}" autocomplete="off" required><button type="button" class="icon-button" data-action="attach-document" aria-label="Attach a document">${icon('paperclip')}</button><button type="button" class="icon-button" data-action="attach-image" aria-label="Upload an image">${icon('image')}</button></div><button type="submit" class="send" aria-label="Send message">${icon('arrow')}</button></form>`}
function title(eyebrow,title,sub){return `<div class="section-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div><div class="heading-brand">${icon('cloud')}<span><b>CloudCore AI</b><small>A product of PTCL Smart Cloud</small></span></div></div>`}
const sampleSummary='This example document outlines PTCL’s enterprise connectivity solutions including dedicated internet, MPLS, cloud services and managed support SLAs for corporate clients. It highlights key service features, deployment options, benefits and commercial terms.';
function documents(){return `${title('DOCUMENT INTELLIGENCE','Document Insight','Upload, analyze and get key information from your documents using CloudCore AI.')}<div class="document-layout"><div><section class="panel upload-panel"><div class="dropzone" data-drop="document"><span class="upload-cloud">${icon('cloud')}${icon('upload')}</span><h3>${docFile?esc(docFile.name):'Drag and drop your file here'}</h3><p>${docFile?'Ready for review on this device':'or <button data-action="choose-document">click to browse</button>'}</p><small>Supports PDF, DOCX, PPTX, XLSX, TXT (Max 50MB)</small><button class="primary" data-action="choose-document">${icon('folder')} ${docFile?'Choose Another File':'Choose File'}</button></div><div class="divider-label"><span></span>Or upload from<span></span></div><div class="upload-sources"><button data-action="choose-document">${icon('folder')}My Device</button><button data-action="cloud-source" data-source="Google Drive"><span class="provider drive">▲</span>Google Drive</button><button data-action="cloud-source" data-source="OneDrive"><span class="provider onedrive">${icon('cloud')}</span>OneDrive</button><button data-action="cloud-source" data-source="SharePoint"><span class="provider sharepoint">S</span>SharePoint</button></div></section><section class="panel recent-docs"><div class="panel-heading">${icon('history')}<h2>Recent Uploaded Documents</h2><button data-action="view-documents">View All ${icon('chevron')}</button></div><div class="document-row"><span class="pdf-icon">${docFile?esc(docFile.name.split('.').pop().toUpperCase().slice(0,4)):'PDF'}</span><div><b>${docFile?esc(docFile.name):'PTCL_Enterprise_Proposal.pdf'}</b><small>${docFile?'Selected just now · '+(docFile.size/1048576).toFixed(2)+' MB':'Example document · 4.2 MB'}</small></div><span class="status">${icon(docFile?'file':'check')}${docFile?'Ready':'Example'}</span></div></section></div><div><section class="panel summary-panel"><div class="panel-heading">${icon('spark')}<div><h2>AI Summary</h2><p>Get instant insights and key information from your document.</p></div></div><div class="summary-content"><div class="tabs" role="tablist" aria-label="Document analysis">${['Summary','Key Points','Actions'].map(t=>`<button role="tab" aria-selected="${docTab===t}" class="${docTab===t?'active':''}" data-action="doc-tab" data-tab="${t}">${t}</button>`).join('')}</div><div class="summary-body"><span class="summary-file">${icon('file')}</span><div>${docFile?'<b>Your document is ready.</b><p>Document analysis requires an AI service connection. Your file remains on this device.</p>':docTab==='Summary'?`<span class="example-label">EXAMPLE ANALYSIS</span><p>${sampleSummary}</p>`:docTab==='Key Points'?'<span class="example-label">EXAMPLE ANALYSIS</span><ul><li>Enterprise connectivity and dedicated internet</li><li>Cloud services and deployment options</li><li>Managed support and service-level agreements</li></ul>':'<span class="example-label">EXAMPLE ANALYSIS</span><ul><li>Review deployment requirements</li><li>Compare connectivity options</li><li>Confirm service-level expectations</li></ul>'}</div></div><div class="summary-meta"><span>${icon('file')} ${docFile?'File selected':'2,304 words'}</span><span>${icon('history')} ${docFile?'Awaiting analysis':'Example preview'}</span><button class="outline" data-action="full-analysis">View Full Analysis ${icon('arrow')}</button></div></div></section><section class="panel smart-actions"><div class="panel-heading">${icon('spark')}<div><h2>Smart Actions</h2><p>Turn your documents into actionable intelligence.</p></div></div><div class="action-grid">${[['file','Generate Executive Summary','Get a concise overview of the document.'],['file','Extract Key Terms','Identify important entities, terms and definitions.'],['grid','Compare with Another Document','Find similarities and differences across documents.'],['chat','Ask Questions about this Document','Chat with your document using CloudCore AI.']].map(([i,t,d])=>`<button data-action="document-action" data-title="${t}"><span class="mini-icon">${icon(i)}</span><span><b>${t}</b><small>${d}</small></span>${icon('chevron')}</button>`).join('')}</div></section></div></div>`}
function images(){return `<div class="breadcrumb"><a href="#home">CloudCore AI</a>${icon('chevron')}<span>Image Analysis</span></div><div class="image-heading"><span class="feature-icon">${icon('image')}</span><div><h1>Image Analysis</h1><h2>Understand and analyze images with AI.</h2><p>Upload an image to identify, analyze and extract meaningful information. Get instant insights,<br>object detection, text extraction and more — powered by CloudCore AI.</p></div><div class="image-motto">Smarter AI.<br>Stronger Business.<br><b>A More Connected Pakistan.</b></div></div><div class="image-layout"><section class="panel image-upload"><div class="tabs image-tabs" role="tablist" aria-label="Image source"><button role="tab" aria-selected="${imageMode==='upload'}" class="${imageMode==='upload'?'active':''}" data-action="image-mode" data-mode="upload">${icon('image')}Upload Image</button><button role="tab" aria-selected="${imageMode==='url'}" class="${imageMode==='url'?'active':''}" data-action="image-mode" data-mode="url">${icon('link')}Analyze from URL</button></div>${imageMode==='upload'?`<div class="dropzone" data-drop="image">${imageURL?`<img class="uploaded-preview" src="${esc(imageURL)}" alt="Selected image preview">`:`<span class="upload-cloud">${icon('cloud')}${icon('upload')}</span>`}<h3>${imageFile?esc(imageFile.name):imageURL?'Image selected':'Drag and drop your image here'}</h3><p>or <button data-action="choose-image">click to browse</button></p><small>Supports JPG, PNG, WEBP (Max 20MB)</small><button class="soft-button" data-action="choose-image">${icon('upload')} ${imageURL?'Choose Another Image':'Choose Image'}</button></div>`:`<form id="url-form" class="url-form"><span class="feature-icon">${icon('link')}</span><h3>Add an image URL</h3><p>Paste a direct HTTPS link to a JPG, PNG or WEBP image.</p><input name="url" type="url" placeholder="https://example.com/image.jpg" aria-label="Image URL" required><button class="primary" type="submit">Load Image ${icon('arrow')}</button></form>`}<div class="examples-heading"><h3>Try with these examples</h3><p>Click an example to explore the preview</p></div><div class="image-examples">${[['building','Enterprise Campus','campus'],['image','Screenshots','screenshot'],['signal','Infrastructure Sites','infrastructure'],['grid','Diagrams & Flowcharts','diagram']].map(([i,t,id])=>`<button data-action="example-image" data-example="${id}"><div class="example-picture ${id}">${id==='campus'||id==='infrastructure'?'<img src="assets/hero.png" alt="PTCL enterprise campus">':id==='screenshot'?'<img src="assets/reference-home.png" alt="Example business dashboard screenshot">':`<div class="diagram-thumb">${icon('cloud')}<span>│</span><div>${icon('building')}${icon('chip')}${icon('cloud')}</div></div>`}</div><span>${t}</span></button>`).join('')}</div></section><section class="panel image-results"><div class="panel-heading">${icon('spark')}<div><h2>AI Analysis Results</h2><p>Insights and information extracted from your image.</p></div><span class="powered">${icon('chip')}CloudCore AI</span></div><div class="analysis-empty"><span>${icon(imageURL?'image':'file')}${!imageURL?icon('search'):''}</span><h3>${imageURL?'Your image is ready for analysis':'Upload an image to see AI analysis results'}</h3><p>${imageURL?'An AI service connection is needed to identify objects, extract text and interpret your image. Your local upload stays on this device.':'Our AI will analyze the image and provide detailed insights,<br>including detected objects, text, context and recommendations.'}</p></div><div class="discover"><div class="discover-title">${icon('bulb')}<b>What you can discover</b><small>Advanced vision AI</small></div><div class="discover-grid">${[['box','Identify Objects','Detect equipment, infrastructure, people and more'],['file','Extract Text (OCR)','Read text from images, labels, screens and documents'],['chip','Understand Context','Get intelligent insights and business relevance'],['grid','Detect Diagrams','Recognize charts, diagrams and flowcharts'],['settings','Technical Analysis','Analyze network equipment, sites and infrastructure'],['chart','Generate Recommendations','Get actionable insights for business decisions']].map(([i,t,d])=>`<div><span class="mini-icon">${icon(i)}</span><span><b>${t}</b><p>${d}</p></span></div>`).join('')}</div></div></section></div>`}
function assistant(){return `${title('YOUR INTELLIGENT WORKSPACE','AI Assistant','Answers, ideas and a little help moving your business forward.')}<section class="chat-panel panel"><div class="chat-top">${icon('cloud')}<strong>CloudCore AI</strong><span>Frontend preview</span><button class="icon-button" data-action="new-chat" aria-label="Start new chat">${icon('plus')}</button></div><div class="messages" aria-live="polite">${messages.length?messages.map(m=>`<div class="message ${m.role}"><span class="message-avatar">${m.role==='user'?'A':icon('cloud')}</span><div>${esc(m.content).replace(/\n/g,'<br>')}</div></div>`).join(''):`<div class="chat-welcome"><span class="feature-icon">${icon('chat')}</span><h2>What can I help you with?</h2><p>Bring your questions. Let’s find a way forward.</p><div class="chat-starters">${['Explore PTCL cloud solutions','Help me draft a proposal','How can I analyze a document?','What can Image Analysis do?'].map(t=>`<button data-action="suggestion" data-prompt="${t}">${t}${icon('arrow')}</button>`).join('')}</div></div>`}</div>${composer('chat')}<p class="chat-caption">CloudCore AI frontend preview · Connect an AI service to enable live responses.</p></section>`}
function history(){const filtered=chats.filter(c=>c.title.toLowerCase().includes(historySearch.toLowerCase()));return `${title('YOUR CONVERSATIONS','Chat History','Pick up where you left off. Your conversations are saved on this device.')}<section class="panel history-panel"><div class="history-toolbar"><label>${icon('search')}<input id="history-search" aria-label="Search conversations" placeholder="Search your conversations..." value="${esc(historySearch)}"></label><button class="primary" data-action="new-chat">${icon('plus')}New Chat</button></div><div id="history-list">${filtered.length?filtered.map(c=>`<div class="history-row"><span class="mini-icon">${icon('chat')}</span><button class="history-open" data-action="open-chat" data-id="${c.id}"><b>${esc(c.title)}</b><small>${new Date(c.updated).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})} · ${c.messages.filter(m=>m.role==='user').length} messages</small></button><button class="icon-button" data-action="delete-chat" data-id="${c.id}" aria-label="Delete conversation">${icon('trash')}</button></div>`).join(''):`<div class="history-empty"><span class="feature-icon">${icon('history')}</span><h2>${historySearch?'No matching conversations':'Your next great idea starts here'}</h2><p>${historySearch?'Try searching with a different word.':'Start a conversation with CloudCore AI and find it here whenever you need it.'}</p><button class="outline" data-action="new-chat">Start a new chat ${icon('arrow')}</button></div>`}</div></section>`}
function modal(content){$('#dialog-content').innerHTML=content;$('#dialog').showModal()}
function saveChats(){try{localStorage.setItem('cloudcore-chats',JSON.stringify(chats))}catch{toast('Your browser could not save chat history.')}}
function sendMessage(t){t=t.trim();if(!t)return;messages.push({role:'user',content:t});let response='This is the CloudCore AI frontend preview. Connect an AI service to receive live answers. You can already explore Document Insight, preview uploaded images and revisit conversations in Chat History.';if(/document|pdf|summari/i.test(t))response='Open Document Insight to select or drag in a PDF, DOCX, PPTX, XLSX or text file (up to 50 MB). You can explore an example summary and its Key Points and Actions tabs. Analysis of your own files will be available once an AI service is connected.';else if(/image|picture/i.test(t))response='Open Image Analysis to upload a JPG, PNG or WEBP image (up to 20 MB), or load one from an HTTPS URL. You can preview the image now. Object detection, OCR and contextual analysis require an AI service connection.';messages.push({role:'assistant',content:response});if(!currentChat)currentChat=String(Date.now());const data={id:currentChat,title:messages.find(m=>m.role==='user').content.slice(0,90),updated:Date.now(),messages:[...messages]};chats=[data,...chats.filter(c=>c.id!==currentChat)];saveChats();if(location.hash==='#assistant'){route();$('.messages').scrollTop=$('.messages').scrollHeight}else location.hash='assistant'}
function selectDocument(file){if(!file)return;if(!/\.(pdf|docx|pptx|xlsx|txt|md)$/i.test(file.name))return toast('Please choose a PDF, DOCX, PPTX, XLSX or text file.');if(file.size>50*1048576)return toast('Please choose a document smaller than 50 MB.');docFile=file;location.hash='documents';route();toast('Document selected. Your file stays on this device.')}
function selectImage(file){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type))return toast('Please choose a JPG, PNG or WEBP image.');if(file.size>20*1048576)return toast('Please choose an image smaller than 20 MB.');if(imageURL.startsWith('blob:'))URL.revokeObjectURL(imageURL);imageFile=file;imageURL=URL.createObjectURL(file);imageMode='upload';location.hash='images';route()}
function actions(a,el){if(a==='new-chat'){messages=[];currentChat=null;location.hash='assistant';route()}else if(a==='suggestion'){const t=el.dataset.prompt;if(t==='Summarize this document')location.hash='documents';else if(t==='What is in this image?')location.hash='images';else sendMessage(t)}else if(a==='choose-document'||a==='attach-document')$('#document-input').click();else if(a==='choose-image'||a==='attach-image')$('#image-input').click();else if(a==='doc-tab'){docTab=el.dataset.tab;route()}else if(a==='image-mode'){imageMode=el.dataset.mode;route()}else if(a==='example-image'){imageFile=null;imageURL=el.dataset.example==='screenshot'?'assets/reference-home.png':el.dataset.example==='diagram'?'assets/diagram.svg':'assets/hero.png';imageMode='upload';route();toast('Example selected. Connect an AI service for image analysis.')}else if(a==='cloud-source')modal(`<h2>Connect ${el.dataset.source}</h2><p>Cloud storage connections will be available when the account integration is configured. For now, download your document and choose it from your device.</p><button class="primary" data-action="choose-document">Choose a local file</button>`);else if(a==='full-analysis'||a==='document-action')modal(`<span class="feature-icon">${icon('file')}</span><h2>${el.dataset.title||'Document Analysis'}</h2><p>${docFile?'Your document is selected. Connect an AI service to analyze its contents.':'Example analysis — PTCL Enterprise Proposal'}</p>${!docFile?`<p>${sampleSummary}</p><h3>Key points</h3><ul><li>Enterprise connectivity and cloud services</li><li>Flexible deployment options</li><li>Managed support and service-level agreements</li></ul>`:''}`);else if(a==='view-documents')modal(`<h2>Recent Documents</h2><p>${docFile?esc(docFile.name)+' — selected on this device.':'No documents uploaded yet. The proposal displayed is an example.'}</p>`);else if(a==='menu')$('.sidebar').classList.toggle('mobile-open');else if(a==='close-dialog')$('#dialog').close();else if(a==='open-chat'){const c=chats.find(c=>c.id===el.dataset.id);messages=[...c.messages];currentChat=c.id;location.hash='assistant'}else if(a==='delete-chat')modal(`<h2>Delete this conversation?</h2><p>This removes the conversation from this device.</p><div class="dialog-actions"><button class="outline" data-action="close-dialog">Cancel</button><button class="primary" data-action="confirm-delete" data-id="${el.dataset.id}">Delete conversation</button></div>`);else if(a==='confirm-delete'){chats=chats.filter(c=>c.id!==el.dataset.id);saveChats();route();toast('Conversation deleted.')}else if(a==='settings')modal('<h2>Settings</h2><p>Chat history is saved only in this browser. Files are previewed on your device.</p><h3>AI connection</h3><p>This frontend is ready for a backend integration. Live answers and file analysis are not connected yet.</p>');else if(a==='profile')modal(`<span class="avatar">A</span><h2>Welcome, Ali</h2><p>You’re exploring CloudCore AI in preview mode.</p><a href="#landing" class="outline">Back to website</a>`);else if(a==='help')modal('<h2>How can we help?</h2><p><b>AI Assistant:</b> Start a conversation and explore the chat interface.</p><p><b>Document Insight:</b> Upload a file and explore an example analysis.</p><p><b>Image Analysis:</b> Preview an uploaded image or use a direct image URL.</p><p><b>Chat History:</b> Reopen or delete conversations saved on this device.</p>');else if(a==='solutions')modal(`<h2>PTCL Business Solutions</h2><p>Explore connectivity, cloud, security and intelligent support.</p><div class="solution-list">${[['signal','Reliable Connectivity','Keep your business connected.'],['cloud','Cloud & Data Solutions','Infrastructure that grows with you.'],['shield','Cyber Security','Protect your business and its data.'],['chip','AI-Powered Support','Find the right support for your business.']].map(([i,t,d])=>`<div>${icon(i)}<span><b>${t}</b><p>${d}</p></span></div>`).join('')}</div>`);bindDialog()}
function bindDialog(){document.querySelectorAll('#dialog [data-action]').forEach(el=>el.onclick=()=>actions(el.dataset.action,el))}
const baseBind=bind;bind=function(){baseBind();document.querySelectorAll('.composer').forEach(f=>f.onsubmit=e=>{e.preventDefault();sendMessage(new FormData(f).get('prompt'))});if($('#search-form'))$('#search-form').onsubmit=e=>{e.preventDefault();const q=$('#search-form input').value.toLowerCase();const match=navs.find(n=>n[2].toLowerCase().includes(q));if(q&&match)location.hash=match[0];else if(q)sendMessage(q)};if($('#document-input'))$('#document-input').onchange=e=>selectDocument(e.target.files[0]);if($('#image-input'))$('#image-input').onchange=e=>selectImage(e.target.files[0]);document.querySelectorAll('[data-drop]').forEach(d=>{d.ondragover=e=>{e.preventDefault();d.classList.add('dragging')};d.ondragleave=()=>d.classList.remove('dragging');d.ondrop=e=>{e.preventDefault();d.classList.remove('dragging');(d.dataset.drop==='image'?selectImage:selectDocument)(e.dataTransfer.files[0])}});if($('#url-form'))$('#url-form').onsubmit=e=>{e.preventDefault();const url=new FormData(e.target).get('url');try{if(new URL(url).protocol!=='https:')throw Error();}catch{return toast('Please enter a valid HTTPS image URL.')}const image=new Image();image.onload=()=>{imageFile=null;imageURL=url;imageMode='upload';route()};image.onerror=()=>toast('The image could not be loaded. Check the link or upload a file.');image.src=url};if($('#history-search'))$('#history-search').oninput=e=>{historySearch=e.target.value;const start=e.target.selectionStart;route();$('#history-search').focus();$('#history-search').setSelectionRange(start,start)};if($('#dialog'))$('#dialog').onclick=e=>{if(e.target===$('#dialog'))$('#dialog').close()};};
window.addEventListener('hashchange',route);route();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'navigate_cloudcore',title:'Open a CloudCore AI screen',description:'Navigate to a CloudCore AI frontend screen. Does not send messages or upload files.',inputSchema:{type:'object',properties:{screen:{type:'string',enum:['landing','home','assistant','documents','images','history']}},required:['screen'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!['landing','home','assistant','documents','images','history'].includes(input.screen))throw new Error('Choose a supported CloudCore AI screen.');location.hash=input.screen;route();return{screen:input.screen,status:'opened'}}})).catch(()=>{})}catch{}}
